//! export type AttachmentConfig = {
//!   image?: ImageAttachmentConfig
//! }
//!
//! export type Config = {
//!   $schema?: string
//!   shell?: string
//!   logLevel?: LogLevel
//!   server?: ServerConfig
//!   command?: {
//!     [key: string]: {
//!       template: string
